{
  "propositions": [
    {"id": "P1", "text": "Empresas devem compensar suas emissões de gases de efeito estufa comprando créditos de carbono gerados por projetos de redução de emissões ou de captura de carbono."},
    {"id": "P2", "text": "Comunidades tradicionais devem ter direito de aprovar projetos de crédito de carbono e participar da repartição de benefícios."},
    {"id": "P3", "text": "A regulamentação do mercado de carbono deve garantir a autodeterminação e a autonomia dos povos indígenas e tradicionais."}
